{"command": "python - <<'PY'
from jc.parsers.asn1crypto.core import *
from copy import copy,deepcopy
x=Integer(5); print('tag base',x.dump().hex())
for kw in ({'implicit':0},{'explicit':0},{'implicit':('application',3)},{'explicit':('application',3)}):
 y=Integer(5,**kw); print(kw,y.dump().hex(),y.class_,y.tag,y.implicit,y.explicit, y.native)
print('retag',x.retag({'implicit':2}).dump().hex())
print('retag legacy',x.retag('explicit',2).dump().hex())
print('untag',Integer(5,explicit=2).untag().dump().hex())
print('copy',copy(x).dump().hex(),deepcopy(x).native,x==Integer(5))
for data,kw in [(bytes.fromhex('800105'),{'implicit':0}),(bytes.fromhex('a003020105'),{'explicit':0})]:
 try:
  y=Integer.load(data,**kw); print('loadtag',data.hex(),kw,y.native,y.dump().hex())
 except Exception as e: print('loadtag ERR',type(e),e)
PY"}

