from jc.parsers.asn1crypto.core import *
class C(Choice):
 _alternatives=[('number',Integer),('text',UTF8String)]
for args in [dict(name='number',value=5),dict(name={'text':'hi'}),dict(name=('number',7))]:
 c=C(**args); print(args,c.name,c.native,c.dump().hex(),type(c.chosen).__name__)
for data in [Integer(9).dump(),UTF8String('yo').dump()]:
 c=C.load(data); print('load',data.hex(),c.name,c.native,c.dump().hex())
try: C(name='bad',value=1)
except Exception as e: print('bad name',type(e).__name__,str(e).splitlines()[0])
try: C(implicit=1)
except Exception as e: print('implicit',type(e).__name__,str(e).splitlines()[0])
a=Any(value=Integer(42)); print('any',a.native,a.parsed.native,a.dump().hex())
b=Any(value=UTF8String('x')); print('any generic',b.parsed, type(b.parsed).__name__, b.parse().native)
try: Any(value=5)
except Exception as e: print('any bad',type(e).__name__,str(e).splitlines()[0])
pos=ParsableOctetString(parsed=Integer(42)); print('pos',pos.dump().hex(),pos.native,type(pos.parsed).__name__,bytes(pos).hex())
pos2=ParsableOctetString(Integer(42).dump()); print('pos2',pos2.parse().native,pos2.native)
PY"}

{"command": "python - <<'PY'
from jc.parsers.asn1crypto.core import *
class S(Set):
 _fields=[('flag',Boolean),('num',Integer),('text',UTF8String,{'optional':True})]
s=S({'num':5,'flag':True}); print('set',s.dump().hex(),s.native)
print('parsed',S.load(s.dump()).native)
try: S.load(bytes.fromhex('30060201050101ff'))
except Exception as e: print('set load malformed',type(e).__name__,e)
try: S({'bogus':1})
except Exception as e: print('unknown',type(e).__name__,str(e).splitlines()[0])
class IS(SetOf): _child_spec=Integer
x=IS([3,1,2]); print('setof',x.dump().hex(),x.native)
y=IS.load(x.dump()); print('setof loaded',y.native,y.dump().hex())
print('contains',Integer(1) in x, Integer(4) in x)
x.append(0); print('setof append',x.dump().hex(),x.native)
PY"}

