def cert(exts=None, subj=None):
 tbs={'version':'v3','serial_number':1,'signature':{'algorithm':'sha256_rsa'},'issuer':name,'validity':{'not_before':{'utc_time':'200101000000Z'},'not_after':{'utc_time':'300101000000Z'}},'subject':subj or name,'subject_public_key_info':pki}
