 return x509.Certificate({'tbs_certificate':tbs,'signature_algorithm':{'algorithm':'sha256_rsa'},'signature_value':b'sig'})
def san(vals):
 return [x509.Extension({'extn_id':'subject_alt_name','extn_value':x509.GeneralNames([x509.GeneralName(name='dns_name',value=v) for v in vals])})]
