class TestCertificatePolicyExtension:
    def test_ca_and_max_path_length(self):
        no_constraints = _certificate()
        assert no_constraints.ca is None
        assert no_constraints.max_path_length is None

        ca_false = _certificate(extensions=[
            _extension(
                'basic_constraints',
                x509.BasicConstraints({'ca': False}),
            ),
        ])
        assert ca_false.ca is False
        assert ca_false.max_path_length is None

        ca_no_path = _certificate(extensions=[
            _extension(
                'basic_constraints',
                x509.BasicConstraints({'ca': True}),
            ),
        ])
        assert ca_no_path.ca is True
        assert ca_no_path.max_path_length is None

        ca_with_path_zero = _certificate(extensions=[
            _extension(
                'basic_constraints',
                x509.BasicConstraints({'ca': True, 'path_len_constraint': 0}),
            ),
        ])
        assert ca_with_path_zero.ca is True
        assert ca_with_path_zero.max_path_length == 0

    def test_self_issued_and_self_signed_states(self):
        subject = _name('example.com')
        different_subject = _name('other.example.com')

        self_issued = _certificate(subject=subject, issuer=subject)
        assert self_issued.self_issued is True
        assert self_issued.self_signed == 'maybe'

        not_self_issued = _certificate(subject=different_subject, issuer=subject)
        assert not_self_issued.self_issued is False
        assert not_self_issued.self_signed == 'no'

        key_id_only = _certificate(
            subject=subject,
            issuer=subject,
            extensions=[_extension('key_identifier', b'\x01')],
        )
        assert key_id_only.self_signed == 'maybe'

        matching_ids = _certificate(
            subject=subject,
            issuer=subject,
            extensions=[
                _extension('key_identifier', b'\x01'),
                _extension(
                    'authority_key_identifier',
                    x509.AuthorityKeyIdentifier({'key_identifier': b'\x01'}),
                ),
            ],
        )
        assert matching_ids.self_signed == 'maybe'

        mismatched_ids = _certificate(
            subject=subject,
            issuer=subject,
            extensions=[
                _extension('key_identifier', b'\x01'),
                _extension(
                    'authority_key_identifier',
                    x509.AuthorityKeyIdentifier({'key_identifier': b'\x02'}),
                ),
            ],
        )
        assert mismatched_ids.self_signed == 'no'


