def _rich_extensions():
    issuer_name = _name('ca.example.com')
    general_names = x509.GeneralNames([_dns_general_name('example.com')])
    authority_key_identifier = x509.AuthorityKeyIdentifier({
        'key_identifier': b'\x01',
        'authority_cert_issuer': x509.GeneralNames([
            x509.GeneralName(name='directory_name', value=issuer_name),
        ]),
        'authority_cert_serial_number': 99,
    })
    return [
        _extension(
            'subject_directory_attributes',
            x509.SubjectDirectoryAttributes([]),
        ),
        _extension('key_identifier', b'\x01'),
        _extension(
            'key_usage',
            x509.KeyUsage({'digital_signature', 'key_cert_sign'}),
            critical=True,
        ),
        _extension(
            'private_key_usage_period',
            x509.PrivateKeyUsagePeriod({
                'not_before': '20200101000000Z',
                'not_after': '20210101000000Z',
            }),
        ),
        _extension(
            'subject_alt_name',
            x509.GeneralNames([
                _dns_general_name('example.com'),
                _dns_general_name('www.example.com'),
            ]),
        ),
        _extension('issuer_alt_name', general_names),
        _extension(
            'basic_constraints',
            x509.BasicConstraints({'ca': True, 'path_len_constraint': 2}),
            critical=True,
        ),
        _extension(
            'name_constraints',
            x509.NameConstraints({
                'permitted_subtrees': [
                    {'base': _dns_general_name('example.com')},
                ],
            }),
        ),
        _extension('crl_distribution_points', x509.CRLDistributionPoints([])),
        _extension(
            'certificate_policies',
            x509.CertificatePolicies([
                {'policy_identifier': '1.2.3.4'},
            ]),
        ),
        _extension(
            'policy_mappings',
            x509.PolicyMappings([
                {
                    'issuer_domain_policy': '1.2.3.4',
                    'subject_domain_policy': '1.2.3.5',
                },
            ]),
        ),
        _extension('authority_key_identifier', authority_key_identifier),
        _extension(
            'policy_constraints',
            x509.PolicyConstraints({
                'require_explicit_policy': 1,
                'inhibit_policy_mapping': 2,
            }),
        ),
        _extension(
            'extended_key_usage',
            x509.ExtKeyUsageSyntax(['server_auth']),
        ),
        _extension('freshest_crl', x509.CRLDistributionPoints([])),
        _extension('inhibit_any_policy', 5),
        _extension(
            'authority_information_access',
            x509.AuthorityInfoAccessSyntax([
                {
                    'access_method': 'ocsp',
                    'access_location': _uri_general_name(
                        'http://ocsp.example.com'
                    ),
                },
            ]),
        ),
        _extension(
            'subject_information_access',
            x509.SubjectInfoAccessSyntax([
                {
                    'access_method': 'ca_issuers',
                    'access_location': _uri_general_name(
                        'http://ca.example.com/issuer'
                    ),
                },
            ]),
        ),
        _extension('tls_feature', x509.Features([31])),
        _extension('ocsp_no_check', None),
        _extension('1.2.3.99', b'unknown', critical=True),
    ]


class TestCertificateCoreProperties:
    def test_public_properties_and_der_round_trip(self):
        expected_public_key = _public_key_info()
        cert = _certificate(serial_number=123456)

        assert cert.serial_number == 123456
        assert cert.subject.native == OrderedDict([
            ('common_name', 'example.com'),
        ])
        assert cert.issuer.native == OrderedDict([
            ('common_name', 'example.com'),
        ])
        assert cert.public_key.native == expected_public_key.native
        assert cert.signature == b'\xde\xad\xbe\xef'
        assert cert.signature_algo == 'rsassa_pkcs1v15'
        assert cert.hash_algo == 'sha256'
        assert cert.not_valid_before == datetime(
            2024, 1, 1, 0, 0, tzinfo=timezone.utc
        )
        assert cert.not_valid_after == datetime(
            2030, 1, 1, 0, 0, tzinfo=timezone.utc
        )
        assert cert.issuer_serial == cert.issuer.sha256 + b':123456'
        assert cert.self_issued is True
        assert cert.self_signed == 'maybe'
        assert cert.ca is None
        assert cert.max_path_length is None

        loaded = x509.Certificate.load(cert.dump())
        assert loaded.dump() == cert.dump()
        assert loaded.subject == cert.subject
        assert loaded.serial_number == 123456

    def test_hashes_and_fingerprints_are_derived_from_der(self):
        cert = _certificate()

        assert cert.sha1 == hashlib.sha1(cert.dump()).digest()
        assert cert.sha256 == hashlib.sha256(cert.dump()).digest()
        assert cert.sha1_fingerprint == ' '.join(
            '%02X' % byte for byte in cert.sha1
        )
        assert cert.sha256_fingerprint == ' '.join(
            '%02X' % byte for byte in cert.sha256
        )
        assert len(cert.sha1_fingerprint.split(' ')) == 20
        assert len(cert.sha256_fingerprint.split(' ')) == 32


