class TestLoad:
    def test_load_reads_binary_file(self, tmp_path):
        path = tmp_path / "example.toml"
        path.write_bytes(b'title = "example"\n[owner]\nname = "Tom"\n')

        with path.open("rb") as fp:
            assert load(fp) == {"title": "example", "owner": {"name": "Tom"}}

    def test_load_forwards_custom_parse_float(self, tmp_path):
        path = tmp_path / "numbers.toml"
        path.write_bytes(b"small = 0.1\nwhole = 2\n")

        with path.open("rb") as fp:
            result = load(fp, parse_float=Decimal)

        assert result == {"small": Decimal("0.1"), "whole": 2}

    def test_load_accepts_any_binary_readable_object(self):
        fp = io.BytesIO(b"enabled = true\n")
        assert load(fp) == {"enabled": True}

    def test_load_rejects_text_mode_streams(self):
        with pytest.raises(TypeError, match="binary mode"):
            load(io.StringIO("answer = 42\n"))


