        src = """
# leading comment
title = "TOML" # trailing comment

[section]
# comment inside a table
value = 1
# final comment without a newline"""
        assert loads(src) == {"title": "TOML", "section": {"value": 1}}

    def test_parses_values_without_a_final_newline(self):
        assert loads("one = 1\ntwo = 'second'") == {"one": 1, "two": "second"}

